if not Zg then pcall(hU,FU) zu.math.abs=(type(hI)=="function" and hI) or function(v) if v<0 then return -v end return v end end
end
end
end
if Zg then
local Ro={Xi,XK,hU}
local bq=zu.string
if type(bq)=="table" then
Ro[#Ro+1]=bq.char Ro[#Ro+1]=bq.byte Ro[#Ro+1]=bq.sub Ro[#Ro+1]=bq.rep Ro[#Ro+1]=bq.len
